svg.script:
//
    (function() {
      // ESTADO DA ILUSTRAÇÃO
      var state = {
        risk: 'low',  // 'low' (0.4mg) ou 'high' (4-5mg)
        phase: 'pre'  // 'pre', 't1', 't23'
      };

      // REFERÊNCIAS DOS BOTÕES
      var btnLow = document.getElementById('a16p3-btn-low');
      var btnHigh = document.getElementById('a16p3-btn-high');
      var stepPre = document.getElementById('a16p3-step-pre');
      var stepT1 = document.getElementById('a16p3-step-t1');
      var stepT23 = document.getElementById('a16p3-step-t23');

      // ELEMENTOS REATIVOS DO PAINEL
      var phaseMarker = document.getElementById('a16p3-phase-marker');
      var txtDose = document.getElementById('a16p3-txt-dose');
      var txtTarget = document.getElementById('a16p3-txt-target');
      var badgeDoseBg = document.getElementById('a16p3-badge-dose-bg');
      var badgeStatusBg = document.getElementById('a16p3-badge-status-bg');
      var txtStatusTitle = document.getElementById('a16p3-txt-status-title');
      var txtDesc1 = document.getElementById('a16p3-txt-desc-1');
      var txtDesc2 = document.getElementById('a16p3-txt-desc-2');
      var txtDesc3 = document.getElementById('a16p3-txt-desc-3');
      var trapTxt1 = document.getElementById('a16p3-trap-txt1');
      var trapTxt2 = document.getElementById('a16p3-trap-txt2');

      function updateUI() {
        // 1. ATUALIZAR BOTÕES DE RISCO
        if (state.risk === 'low') {
          btnLow.classList.add('a16p3-active');
          btnHigh.classList.remove('a16p3-active');
          txtDose.textContent = '0,4 mg / dia (400 µg)';
          txtDose.setAttribute('fill', 'var(--a16p3-teal-light, #2dd4bf)');
          txtTarget.textContent = 'População Geral';
          badgeDoseBg.setAttribute('fill', 'var(--a16p3-teal-bg, rgba(20, 184, 166, 0.12))');
          badgeDoseBg.setAttribute('stroke', 'var(--a16p3-teal-main, #14b8a6)');
        } else {
          btnLow.classList.remove('a16p3-active');
          btnHigh.classList.add('a16p3-active');
          txtDose.textContent = '4,0 a 5,0 mg / dia (10×)';
          txtDose.setAttribute('fill', 'var(--a16p3-gold-light, #fbbf24)');
          txtTarget.textContent = 'Alto Risco (NTD/Fármaco)';
          badgeDoseBg.setAttribute('fill', 'var(--a16p3-gold-bg, rgba(245, 158, 11, 0.15))');
          badgeDoseBg.setAttribute('stroke', 'var(--a16p3-gold-main, #f59e0b)');
        }

        // 2. ATUALIZAR BOTÕES DE FASE E MARCADOR NA LINHA DO TEMPO
        stepPre.classList.remove('a16p3-active');
        stepT1.classList.remove('a16p3-active');
        stepT23.classList.remove('a16p3-active');

        if (state.phase === 'pre') {
          stepPre.classList.add('a16p3-active');
          phaseMarker.setAttribute('x1', '60');
          phaseMarker.setAttribute('x2', '60');

          badgeStatusBg.setAttribute('fill', 'var(--a16p3-green-bg, rgba(16, 185, 129, 0.12))');
          badgeStatusBg.setAttribute('stroke', 'var(--a16p3-green-main, #10b981)');
          txtStatusTitle.textContent = '✓ JANELA IDEAL (Pré-Concepção)';
          txtStatusTitle.setAttribute('fill', 'var(--a16p3-green-light, #34d399)');

          txtDesc1.textContent = 'Saturação ideal dos estoques foláticos teciduais';
          txtDesc2.textContent = '1 a 3 meses antes da fecundação. Previne falha de';
          txtDesc3.textContent = 'fechamento primário do neuroporo rostral e caudal.';
        } else if (state.phase === 't1') {
          stepT1.classList.add('a16p3-active');
          phaseMarker.setAttribute('x1', '210');
          phaseMarker.setAttribute('x2', '210');

          badgeStatusBg.setAttribute('fill', 'var(--a16p3-teal-bg, rgba(20, 184, 166, 0.12))');
          badgeStatusBg.setAttribute('stroke', 'var(--a16p3-teal-main, #14b8a6)');
          txtStatusTitle.textContent = '⚡ JANELA CRÍTICA EM ANDAMENTO (1ºT)';
          txtStatusTitle.setAttribute('fill', 'var(--a16p3-teal-light, #2dd4bf)');

          txtDesc1.textContent = 'O tubo neural fecha totalmente no dia 28 pós-concepção';
          txtDesc2.textContent = '(6ª semana de amenorreia). Manter o ácido fólico';
          txtDesc3.textContent = 'indispensável até o final do 1º Trimestre (12 semanas).';
        } else {
          stepT23.classList.add('a16p3-active');
          phaseMarker.setAttribute('x1', '445');
          phaseMarker.setAttribute('x2', '445');

          badgeStatusBg.setAttribute('fill', 'var(--a16p3-red-bg, rgba(239, 68, 68, 0.12))');
          badgeStatusBg.setAttribute('stroke', 'var(--a16p3-red-main, #ef4444)');
          txtStatusTitle.textContent = '⚠ FORA DA JANELA DO TUBO (2º/3ºT)';
          txtStatusTitle.setAttribute('fill', 'var(--a16p3-red-light, #f87171)');

          txtDesc1.textContent = 'O tubo neural JÁ ESTÁ FECHADO. Iniciar fólico agora';
          txtDesc2.textContent = 'NÃO previne mais anencefalia ou espinha bífida.';
          txtDesc3.textContent = 'Uso atual visa prevenção de anemia e eritropoiese.';
        }
      }

      // EVENT LISTENERS COM SUPORTE A TOUCH & TECLADO
      btnLow.addEventListener('click', function() { state.risk = 'low'; updateUI(); });
      btnHigh.addEventListener('click', function() { state.risk = 'high'; updateUI(); });

      stepPre.addEventListener('click', function() { state.phase = 'pre'; updateUI(); });
      stepT1.addEventListener('click', function() { state.phase = 't1'; updateUI(); });
      stepT23.addEventListener('click', function() { state.phase = 't23'; updateUI(); });

      // ACESSIBILIDADE VIA TECLADO (ENTER / SPACE)
      var interactiveElems = [btnLow, btnHigh, stepPre, stepT1, stepT23];
      interactiveElems.forEach(function(elem) {
        elem.addEventListener('keydown', function(e) {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            elem.click();
          }
        });
      });

      // INICIALIZAR ESTADO INICIAL
      updateUI();
    })();
  //
